import { describe, expect, it } from 'vitest';
import { canonicalizeParams, sign } from '../../../lib/adapters/aliexpress/sign';

// Expected signatures were independently calculated with Python's standard
// library hmac.new(secret, canonical.encode(), hashlib.sha256).hexdigest().upper()
// and are fixed known-answer vectors, not outputs generated by this module.

describe('AliExpress Open Platform signer (GC-201)', () => {
  it('sorts parameter names and concatenates each name with its value', () => {
    expect(canonicalizeParams({
      timestamp: '2026-10-29T10:00:00Z',
      q: 'red shoes',
      method: 'aliexpress.ds.text.search',
      app_key: '12345',
      sign_method: 'sha256',
    })).toBe(
      'app_key12345methodaliexpress.ds.text.searchqred shoessign_methodsha256timestamp2026-10-29T10:00:00Z',
    );
  });

  it('excludes sign and omits nullish values while preserving empty strings and zero', () => {
    expect(canonicalizeParams({
      z: 0,
      absent: undefined,
      sign: 'must-not-be-signed',
      empty: '',
      nil: null,
      b: 'two',
      a: 'one',
    })).toBe('aonebtwoemptyz0');
  });

  it('matches an independently calculated known-answer vector', () => {
    expect(sign({
      app_key: '12345',
      method: 'aliexpress.ds.text.search',
      sign_method: 'sha256',
      timestamp: '2026-10-29T10:00:00Z',
      q: 'red shoes',
    }, 'test-secret')).toBe(
      '3ECB09C835D7A5EB14B1806D4D0F51D0A8FFE6B13ABDDE4DDCDAEB1388F06FCA',
    );
  });

  it('matches a vector with out-of-order keys, an existing sign, and an empty value', () => {
    expect(sign({
      b: 'two',
      a: 'one',
      sign: 'ignored-existing-sign',
      empty: '',
      z: '0',
    }, 'dummy-secret')).toBe(
      'D0CAFB1097B4312ABE7C74880E86F186ECB8F7DF89A526B7C059253F576983E4',
    );
  });

  it('matches a vector containing API search parameters', () => {
    expect(sign({
      pageNo: '2',
      pageSize: '20',
      countryCode: 'US',
      keyword: 'A&B',
    }, 'fixture-secret')).toBe(
      'F447FB3914F45909903E3EDC1ABB6F0D0E12F0340008815C7AC238E353C84695',
    );
  });

  it('rejects an empty secret', () => {
    expect(() => sign({ app_key: '12345' }, '')).toThrow(
      'AliExpress app secret must not be empty',
    );
  });
});
